{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "Donepezil, a structurally related dimethoxyaryl basic CNS drug, has an absolute oral bioavailability of 100% in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Valbenazine, a VMAT2 inhibitor with a tetrabenazine-like core and basic amine prodrug modification, has an absolute oral bioavailability of approximately 49% in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Verapamil, a dimethoxyphenyl basic amine drug, has a mean absolute bioavailability of about 50% in normal subjects, supporting F >= 20% in the absence of enzyme induction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Tetrabenazine has very low absolute oral bioavailability (mean ~4.9%) in patients, but this reflects its specific ketone-reduction first-pass liability and has low transferability to the query's lactam-containing structure.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C33"],
      "claim": "Almorexant has low absolute oral bioavailability (~11%), but its low structural similarity and very low transferability to the query limit its weight.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F >= 20%). Transferable evidence from donepezil (F ~100%) and valbenazine (F ~49%) supports high oral bioavailability; verapamil in normal subjects also supports F >= 20%. Low-F tetrabenazine and almorexant have low transferability/structural relevance, and tetrabenazine's ketone-reduction liability is not present in the query's lactam. The physicochemical prior is mixed and not decisive.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the exact query molecule.",
    "The query's low neutral fraction due to basic pKa 9.05 may affect absorption, but no permeability data are available.",
    "Potential first-pass metabolism of the tertiary amine side chain is unknown.",
    "Verapamil low-F records under rifampin are condition-specific and not applicable to the query without co-treatment.",
    "No data on food effects or transporter involvement for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

